<script setup lang="ts">
import { computed, reactive, ref } from 'vue';
import { useRecordsStore } from '../stores/recordsStore';
const records = useRecordsStore(); const query = ref(''); const type = ref('all'); const form = reactive({ title: '', content: '', type: '摘抄', tags: '', source: '', note: '' });
const items = computed(() => records.materials.filter(item => (type.value === 'all' || item.type === type.value) && [item.title, item.content, item.source, ...(Array.isArray(item.tags) ? item.tags : [])].join(' ').toLowerCase().includes(query.value.toLowerCase())));
function add() { if (!form.title.trim()) return; records.addMaterial({ ...form, title: form.title.trim(), tags: form.tags.split(/[,，\s]+/).map(item => item.trim()).filter(Boolean) }); Object.assign(form, { title: '', content: '', type: '摘抄', tags: '', source: '', note: '' }); }
</script>
<template><section class="page active" id="page-materials"><header class="page-header"><div class="page-title">素材库</div></header><form class="card" @submit.prevent="add"><div class="form-row"><div class="form-group"><label>标题</label><input v-model="form.title" required /></div><div class="form-group"><label>类型</label><select v-model="form.type"><option v-for="item in ['金句','提示词','摘抄','观点','方法']" :key="item">{{ item }}</option></select></div></div><div class="form-group"><label>内容</label><textarea v-model="form.content" /></div><div class="form-row"><div class="form-group"><label>标签</label><input v-model="form.tags" /></div><div class="form-group"><label>来源</label><input v-model="form.source" /></div></div><button class="btn btn-primary">保存素材</button></form><div class="filter-bar"><input v-model="query" type="search" placeholder="搜索素材" /><select v-model="type"><option value="all">全部类型</option><option v-for="item in ['金句','提示词','摘抄','观点','方法']" :key="item">{{ item }}</option></select></div><div class="material-grid"><article v-for="item in items" :key="item.id" :class="['material-card', `type-${item.type}`]"><span class="item-type">{{ item.type }}</span><h2>{{ item.title }}</h2><p>{{ item.content }}</p><div class="item-meta"><span v-for="tag in Array.isArray(item.tags) ? item.tags : []" :key="String(tag)">{{ tag }}</span></div><button class="btn btn-danger" type="button" @click="records.remove('materials', String(item.id))">删除</button></article></div><div v-if="!items.length" class="empty-state">暂无匹配素材。</div></section></template>
